from scipy.stats import chi2_contingency

def process(filter_known_causes_jan_mar):
    contingency = pd.crosstab(filter_known_causes_jan_mar['region'], filter_known_causes_jan_mar['cause'])
    chi2, p, dof, expected = chi2_contingency(contingency)
    result = pd.DataFrame({
        'chi2_statistic': [round(chi2, 3)],
        'p_value': [round(p, 3)],
        'degrees_of_freedom': [dof]
    })
    return result
